<script setup lang="ts">
import { computed, ref } from 'vue'
import type { ForumConversation, ForumNotification, ForumUser } from '../../../types/forum'
import ForumHeader from '../components/ForumHeader.vue'
import ForumAvatar from '../components/ForumAvatar.vue'
import ForumEmptyState from '../components/ForumEmptyState.vue'
const props=defineProps<{conversations:ForumConversation[];notifications?:ForumNotification[];users?:ForumUser[]}>()
const emit=defineEmits<{(e:'back'):void;(e:'click-conversation',conversation:ForumConversation):void;(e:'click-user',user:ForumUser):void;(e:'create-group',name:string,members:string[]):void}>()
const tab=ref<'notice'|'direct'|'group'|'request'>('direct');const creating=ref(false);const groupName=ref('');const members=ref<string[]>([])
const rows=computed(()=>props.conversations.filter(item=>tab.value==='group'?item.kind==='group':tab.value==='request'?item.requestState==='pending':item.kind!=='group'&&item.requestState!=='pending'))
const submit=()=>{if(!groupName.value.trim())return;emit('create-group',groupName.value,members.value);groupName.value='';members.value=[];creating.value=false;tab.value='group'}
</script>
<template>
  <div class="messages-view"><ForumHeader title="消息" show-back @back="emit('back')"><template #right><button class="head-action" @click="creating=!creating">{{creating?'取消':'建群'}}</button></template></ForumHeader>
    <nav class="message-tabs"><button :class="{active:tab==='notice'}" @click="tab='notice'">通知</button><button :class="{active:tab==='direct'}" @click="tab='direct'">私信</button><button :class="{active:tab==='group'}" @click="tab='group'">群</button><button :class="{active:tab==='request'}" @click="tab='request'">请求</button></nav>
    <form v-if="creating" class="group-form" @submit.prevent="submit"><input v-model="groupName" maxlength="24" placeholder="群名"/><div class="member-picks"><label v-for="user in users" :key="user.id"><input v-model="members" type="checkbox" :value="user.id"/><span>{{user.name}}</span></label></div><button :disabled="!groupName.trim()">创建群聊</button></form>
    <div class="message-scroll">
      <template v-if="tab==='notice'"><button v-for="notice in notifications" :key="notice.id" class="notice-row"><span class="notice-dot"></span><span><b>{{notice.text}}</b><small>{{new Date(notice.createdAt).toLocaleString('zh-CN')}}</small></span></button><ForumEmptyState v-if="!notifications?.length" title="暂无通知" description="点赞、回复、关注和圈子消息会出现在这里"/></template>
      <template v-else><button v-for="conv in rows" :key="conv.id" class="conversation-row" @click="emit('click-conversation',conv)"><div class="avatar-col"><ForumAvatar :src="conv.user.avatar" :name="conv.user.name" size="md" @click.stop="emit('click-user',conv.user)"/><span v-if="conv.unreadCount" class="unread-badge">{{conv.unreadCount}}</span></div><span class="info-col"><span><b>{{conv.user.name}}</b><em>{{conv.lastMessageTime}}</em></span><small>{{conv.lastMessage}}</small></span></button><ForumEmptyState v-if="!rows.length" :title="tab==='group'?'暂无群聊':tab==='request'?'暂无请求':'暂无私信'" description="这里还没有新内容"/></template>
    </div>
  </div>
</template>
<style scoped>
.messages-view{display:flex;flex-direction:column;height:100%;background:var(--sys-bg-primary,#f5f5f7)}.head-action{border:0;background:transparent;color:var(--accent-color,#2b7de9);padding:5px;font-size:12px}.message-tabs{display:flex;gap:3px;padding:7px 10px;background:var(--sys-bg-secondary,#fff);border-bottom:1px solid var(--border-color,rgba(0,0,0,.06))}.message-tabs button{flex:1;height:29px;border:0;border-radius:8px;background:transparent;color:var(--text-secondary,#777);font-size:12px}.message-tabs button.active{background:var(--sys-bg-tertiary,#f0f1f3);color:var(--text-primary,#222);font-weight:600}.group-form{padding:9px 12px;background:var(--sys-bg-secondary,#fff);border-bottom:1px solid var(--border-color,rgba(0,0,0,.06))}.group-form>input{box-sizing:border-box;width:100%;height:32px;border:1px solid var(--border-color,#ddd);border-radius:8px;background:var(--sys-bg-primary,#f7f7f8);padding:0 8px;color:var(--text-primary,#222);font:inherit;font-size:12px}.member-picks{display:flex;gap:5px;overflow:auto;padding:7px 0}.member-picks label{position:relative;flex:0 0 auto}.member-picks input{position:absolute;opacity:0}.member-picks span{display:block;border-radius:999px;background:var(--sys-bg-primary,#f1f2f4);padding:5px 8px;color:var(--text-secondary,#777);font-size:10.5px}.member-picks input:checked+span{background:color-mix(in srgb,var(--accent-color,#576b95) 14%,transparent);color:var(--accent-color,#576b95)}.group-form>button{height:29px;border:0;border-radius:8px;background:var(--accent-color,#2b7de9);color:#fff;padding:0 11px;font-size:11.5px}.group-form>button:disabled{opacity:.35}.message-scroll{flex:1;overflow:auto;background:var(--sys-bg-secondary,#fff)}.conversation-row,.notice-row{display:flex;width:100%;min-width:0;align-items:center;gap:11px;min-height:60px;padding:9px 16px;border:0;border-bottom:1px solid var(--border-color,rgba(0,0,0,.055));background:transparent;color:var(--text-primary,#222);text-align:left}.avatar-col{position:relative;flex:0 0 auto}.unread-badge{position:absolute;top:-2px;right:-2px;display:flex;min-width:15px;height:15px;align-items:center;justify-content:center;border-radius:999px;background:#e05252;color:#fff;font-size:9px}.info-col{display:flex;min-width:0;flex:1;flex-direction:column;gap:4px}.info-col>span{display:flex;min-width:0;align-items:center;justify-content:space-between;gap:9px}.info-col b{overflow:hidden;font-size:13.5px;white-space:nowrap;text-overflow:ellipsis}.info-col em{flex:0 0 auto;color:var(--text-tertiary,#999);font-size:10px;font-style:normal}.info-col small{overflow:hidden;color:var(--text-secondary,#777);font-size:11.5px;white-space:nowrap;text-overflow:ellipsis}.notice-dot{flex:0 0 8px;height:8px;border-radius:50%;background:var(--accent-color,#576b95)}.notice-row>span:last-child{display:flex;min-width:0;flex:1;flex-direction:column;gap:4px}.notice-row b{font-size:12.5px;font-weight:550}.notice-row small{font-size:10px;color:var(--text-tertiary,#999)}@media(max-width:340px){.conversation-row,.notice-row{padding-left:12px;padding-right:12px}}
</style>
